void __osDevMgrMain(void* args) {
    OSIoMesg* mb;
    OSMesg em;
    OSMesg dummy;
    s32 ret;
    OSDevMgr* dm;
    s32 messageSend = 0;

    dm = (OSDevMgr*)args;
    mb = 0 ;
    ret = 0;

    while (1 ) {
        osRecvMesg(dm->cmdQueue, (OSMesg)&mb, 1 );

        if (mb->piHandle != 0  && mb->piHandle->type == 2  &&
            (mb->piHandle->transferInfo.cmdType == 0  ||
             mb->piHandle->transferInfo.cmdType == 1 )) {
            __OSBlockInfo* blockInfo;
            __OSTranxInfo* info;
            info = &mb->piHandle->transferInfo;
            blockInfo = &info->block[info->blockNum];
            info->sectorNum = -1;

            if (info->transferMode != 3 ) {
                blockInfo->dramAddr = (void*)((u32)blockInfo->dramAddr - blockInfo->sectorSize);
            }

            if (info->transferMode == 2  && mb->piHandle->transferInfo.cmdType == 0 ) {
                messageSend = 1;
            } else {
                messageSend = 0;
            }

            osRecvMesg(dm->acsQueue, &dummy, 1 );
            __osResetGlobalIntMask(0x00100401 );
            func_80041A70 (mb->piHandle, (0x05000000  + 0x510) , (info->bmCtlShadow | 0x80000000));

        readblock1:
            osRecvMesg(dm->evtQueue, &em, 1 );
            info = &mb->piHandle->transferInfo;
            blockInfo = &info->block[info->blockNum];

            if (blockInfo->errStatus == 29 ) {
                u32 stat;
                func_80041A70 (mb->piHandle, (0x05000000  + 0x510) , info->bmCtlShadow | 0x10000000 );
                func_80041A70 (mb->piHandle, (0x05000000  + 0x510) , info->bmCtlShadow);
                pi_read_word (mb->piHandle, (0x05000000  + 0x508) , &stat);

                if (stat & 0x02000000 ) {
                    func_80041A70 (mb->piHandle, (0x05000000  + 0x510) , info->bmCtlShadow | 0x01000000 );
                }

                blockInfo->errStatus = 4 ;
                (*(vu32*)((u32)(  (0x04600000  + 0x10)   )|0xA0000000) =(u32)(  (1 << 1)   )) ;
                __osSetGlobalIntMask(0x00100401  | 0x00000800 );
            }

            osSendMesg(mb->hdr.retQueue, mb, 0 );

            if (messageSend == 1 && mb->piHandle->transferInfo.block[0].errStatus == 0 ) {
                messageSend = 0;
                goto readblock1;
            }

            osSendMesg(dm->acsQueue, 0 , 0 );
            if (mb->piHandle->transferInfo.blockNum == 1) {
                osYieldThread();
            }
        } else {
            switch (mb->hdr.type) {
                case ((10)  + 1) :
                    osRecvMesg(dm->acsQueue, &dummy, 1 );
                    ret = dm->dma(0 , mb->devAddr, mb->dramAddr, mb->size);
                    break;
                case ((10)  + 2) :
                    osRecvMesg(dm->acsQueue, &dummy, 1 );
                    ret = dm->dma(1 , mb->devAddr, mb->dramAddr, mb->size);
                    break;
                case ((10)  + 5) :
                    osRecvMesg(dm->acsQueue, &dummy, 1 );
                    ret = dm->edma(mb->piHandle, 0 , mb->devAddr, mb->dramAddr, mb->size);
                    break;
                case ((10)  + 6) :
                    osRecvMesg(dm->acsQueue, &dummy, 1 );
                    ret = dm->edma(mb->piHandle, 1 , mb->devAddr, mb->dramAddr, mb->size);
                    break;
                case ((10)  + 0) :
                    osSendMesg(mb->hdr.retQueue, mb, 0 );
                    ret = -1;
                    break;
                default:
                    ret = -1;
                    break;
            }

            if (ret == 0) {
                osRecvMesg(dm->evtQueue, &em, 1 );
                osSendMesg(mb->hdr.retQueue, mb, 0 );
                osSendMesg(dm->acsQueue, 0 , 0 );
            }
        }
    }
