/* identical to guNormalize in V-RALLY (local match library) (matched), with its names changed by decompdecomp */
/* Scales the vector (x, y, z) in place to unit length. */
void guNormalize(f32 *x, f32 *y, f32 *z) {
    f32 vx;
    f32 vy;
    f32 vz;
    f32 inv_len;

    vx = *x;
